changeSet.sql:
CREATE TABLE price_tiers ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
estate_id uuid NOT NULL, size_sqm numeric(12,2) NOT NULL, price numeric(19,4) NOT NULL, currency varchar(3) NOT NULL, label varchar(255),
PRIMARY KEY (id) );
COMMENT ON COLUMN price_tiers.price IS 'This tier''s own developer-set price. NEVER derived from a single per-sqm rate: larger plots are routinely discounted per square metre (180 sqm at N18,000/sqm while 600 sqm sells at N14,500/sqm), so a per-sqm figure is a DISPLAYED comparison computed for the UI, never an input to pricing. Deriving price from a rate would quietly overcharge every large plot.'; COMMENT ON COLUMN price_tiers.size_sqm IS 'The NOMINAL size this tier represents — what its plots are sold and priced as, not what any of them survey at. See plots.nominal_size_sqm / plots.actual_area_sqm.';
ALTER TABLE price_tiers ADD CONSTRAINT chk_price_tiers_currency CHECK (currency IN ('NGN', 'USD', 'GBP', 'EUR')); -- Money is never negative, and a zero-priced tier is a data entry -- error rather than a giveaway. ALTER TABLE price_tiers ADD CONSTRAINT chk_price_tiers_price_positive CHECK (price > 0); ALTER TABLE price_tiers ADD CONSTRAINT chk_price_tiers_size_positive CHECK (size_sqm > 0);
